package org.animallink.adoption.api; import jakarta.validation.Valid; import java.util.List; import org.animallink.adoption.application.AdoptionHandoverService; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1") public class AdoptionHandoverController{private final AdoptionHandoverService s;public AdoptionHandoverController(AdoptionHandoverService s){this.s=s;}@PostMapping("/governance/selections/{selectionId}/handover") public ResponseEntity<AdoptionHandoverDtos.GovernanceResponse> initiate(@PathVariable(name="selectionId") String id,@Valid @RequestBody AdoptionHandoverDtos.InitiateRequest r){var x=s.initiate(id,r.scheduledAt(),r.note());return ResponseEntity.status(x.created()?HttpStatus.CREATED:HttpStatus.OK).body(AdoptionHandoverDtos.GovernanceResponse.from(x.view()));}@GetMapping("/governance/selections/{selectionId}/handover") public AdoptionHandoverDtos.GovernanceResponse read(@PathVariable(name="selectionId") String id){return AdoptionHandoverDtos.GovernanceResponse.from(s.governance(id));}@GetMapping("/me/handovers") public List<AdoptionHandoverDtos.ApplicantResponse> mine(){return s.mine().stream().map(AdoptionHandoverDtos.ApplicantResponse::from).toList();}@PostMapping("/governance/handovers/{handoverId}/complete") public ResponseEntity<AdoptionHandoverDtos.GovernanceResponse> complete(@PathVariable(name="handoverId") String id){var x=s.complete(id);return ResponseEntity.status(x.created()?HttpStatus.OK:HttpStatus.OK).body(AdoptionHandoverDtos.GovernanceResponse.from(x.view()));}@PostMapping("/governance/handovers/{handoverId}/cancel") public ResponseEntity<AdoptionHandoverDtos.GovernanceResponse> cancel(@PathVariable(name="handoverId") String id,@Valid @RequestBody AdoptionHandoverDtos.CancelRequest r){var x=s.cancel(id,r.reason());return ResponseEntity.ok(AdoptionHandoverDtos.GovernanceResponse.from(x.view()));}}
